<template><el-dialog v-model="visible" :title="title" width="min(950px,calc(100vw - 32px))" append-to-body><el-alert v-if="summary" :title="summary" :closable="false" style="margin-bottom:12px"/><el-table :data="rows"><el-table-column prop="contentId" label="内容ID" width="95"/><el-table-column prop="assetId" label="素材ID" width="95"/><el-table-column prop="code" label="类型" min-width="170"/><el-table-column prop="message" label="说明" min-width="240"/><el-table-column prop="url" label="站内路径" min-width="180"/></el-table><template #footer><el-button @click="visible=false">关闭</el-button></template></el-dialog></template><script setup>import {ref} from 'vue';const visible=ref(false),title=ref('检查结果'),rows=ref([]),summary=ref('');function open(name,items,text){title.value=name;rows.value=items;summary.value=text;visible.value=true};defineExpose({open,close:()=>{visible.value=false}})</script>